function primeraIncidencia(esperas, limite) {
  let inspecciones = 0;
  for (let i = 0; i < esperas.length; i++) {
    inspecciones++;
    if (esperas[i] > limite) return [i, inspecciones];
  }
  return [-1, inspecciones];
}
